54	export const NewPlayerForm = ({
55	    players,
56	    onCreatePlayer,
57	    onSendEmail,
58	}: Props) => {
59	    const router = useRouter();
60	    const getPreferredEmail = (player?: PlayerDataType) => {
61	        if (player?.accountEmail) {
62	            return player.accountEmail;
63	        }
64	        if (!player?.extraEmails.length) return '';
65	        const verifiedEmail = player.extraEmails.find((playerEmail) => playerEmail.verified);
66	        /* v8 ignore next -- extraEmails[0] always exists (length > 0 checked above) and always has an email property */
67	        return (verifiedEmail ?? player.extraEmails[0])?.email ?? '';
68	    };
69	
